const statsResponse = $node['Get SendGrid Stats'].json;
const bouncesResponse = $node['Get Recent Bounces'].json;

// Parse stats
const stats = Array.isArray(statsResponse) ? statsResponse : [statsResponse];
let totalSent = 0, totalDelivered = 0, totalOpened = 0;
let totalBounced = 0, totalSpamReports = 0, totalBlocked = 0;

for (const day of stats) {
  const metrics = day.stats?.[0]?.metrics || day.metrics || {};
  totalSent += metrics.requests || 0;
  totalDelivered += metrics.delivered || 0;
  totalOpened += metrics.unique_opens || 0;
  totalBounced += (metrics.bounces || 0) + (metrics.bounce_drops || 0);
  totalSpamReports += metrics.spam_reports || 0;
  totalBlocked += metrics.blocks || 0;
}

// Calculate rates
const deliveryRate = totalSent > 0 ? (totalDelivered / totalSent * 100) : 0;
const openRate = totalDelivered > 0 ? (totalOpened / totalDelivered * 100) : 0;
const bounceRate = totalSent > 0 ? (totalBounced / totalSent * 100) : 0;
const spamRate = totalDelivered > 0 ? (totalSpamReports / totalDelivered * 100) : 0;

// Health assessment
let healthStatus = 'healthy';
const issues = [];

if (deliveryRate < 95) {
  healthStatus = 'warning';
  issues.push(`Low delivery rate: ${deliveryRate.toFixed(1)}% (target: >95%)`);
}
if (bounceRate > 5) {
  healthStatus = 'critical';
  issues.push(`High bounce rate: ${bounceRate.toFixed(1)}% (target: <5%)`);
}
if (spamRate > 0.1) {
  healthStatus = 'critical';
  issues.push(`High spam rate: ${spamRate.toFixed(3)}% (target: <0.1%)`);
}
if (openRate < 15) {
  issues.push(`Low open rate: ${openRate.toFixed(1)}% (benchmark: >20%)`);
  if (healthStatus === 'healthy') healthStatus = 'warning';
}

// Parse bounces
const bounces = Array.isArray(bouncesResponse) ? bouncesResponse : [];
const hardBounces = bounces.filter(b => b.status?.startsWith('5'));

return [{
  json: {
    date: new Date(Date.now() - 24*60*60*1000).toISOString().split('T')[0],
    metrics: {
      sent: totalSent,
      delivered: totalDelivered,
      opened: totalOpened,
      bounced: totalBounced,
      spam_reports: totalSpamReports,
      blocked: totalBlocked
    },
    rates: {
      delivery_rate: Math.round(deliveryRate * 10) / 10,
      open_rate: Math.round(openRate * 10) / 10,
      bounce_rate: Math.round(bounceRate * 10) / 10,
      spam_rate: Math.round(spamRate * 1000) / 1000
    },
    health_status: healthStatus,
    issues: issues,
    hard_bounces_count: hardBounces.length,
    hard_bounce_emails: hardBounces.slice(0, 10).map(b => b.email)
  }
}];

